using System.Collections.ObjectModel;
using System.Globalization;
using TiemChung.Desktop.Services;
namespace TiemChung.Desktop.ViewModels;
public sealed class PromotionViewModel:ViewModelBase
{
 private readonly IPromotionService _service;private string _name="",_description="",_amount="",_feedback="";private DateTime _start=DateTime.Today,_end=DateTime.Today.AddDays(7);private PromotionRecord? _selected;private bool _saving;
 public PromotionViewModel(IPromotionService? service=null){_service=service??new SamplePromotionService();foreach(var x in _service.GetPromotions())Promotions.Add(x);Promotions.CollectionChanged+=(_,_)=>OnPropertyChanged(nameof(HasNoData));SaveCommand=new(_=>Save(),_=>CanSave);DeleteCommand=new(_=>Delete(),_=>CanDelete);NewCommand=new(_=>Clear());}
 public ObservableCollection<PromotionRecord>Promotions{get;}=[];public RelayCommand SaveCommand{get;}public RelayCommand DeleteCommand{get;}public RelayCommand NewCommand{get;}public PromotionRecord? Selected{get=>_selected;set{if(Set(ref _selected,value)){if(value is not null){Name=value.Name;Description=value.Description;Start=value.Starts;End=value.Ends;Amount=value.Discount.ToString(CultureInfo.InvariantCulture);}Refresh();}}}
 public string Name{get=>_name;set{if(Set(ref _name,value))Refresh();}}public string Description{get=>_description;set{if(Set(ref _description,value))Refresh();}}public DateTime Start{get=>_start;set{if(Set(ref _start,value))Refresh();}}public DateTime End{get=>_end;set{if(Set(ref _end,value))Refresh();}}public string Amount{get=>_amount;set{if(Set(ref _amount,value))Refresh();}}public string Feedback{get=>_feedback;private set=>Set(ref _feedback,value);}public string DataSourceLabel=>_service.UseSampleData?"Dữ liệu mẫu":"Chưa có nguồn dữ liệu";public bool HasNoData=>Promotions.Count==0;public bool IsAssigned=>Selected is not null&&_service.IsAssigned(Selected.Id);public bool IsActive(PromotionRecord p)=>p.Starts<=DateTime.Today&&p.Ends>=DateTime.Today;public string Status(PromotionRecord p)=>IsActive(p)?"Đang hoạt động":"Hết hiệu lực";public bool CanSave=>!_saving&&!string.IsNullOrWhiteSpace(Name)&&End>Start&&decimal.TryParse(Amount,NumberStyles.Number,CultureInfo.InvariantCulture,out var a)&&a>=0;public string Validation=>End<=Start?"Thời điểm kết thúc phải sau thời điểm bắt đầu.":decimal.TryParse(Amount,NumberStyles.Number,CultureInfo.InvariantCulture,out var a)&&a<0?"Mức ưu đãi không được âm.":"";public bool CanDelete=>Selected is not null&&!IsAssigned&&!_saving;
 private void Save(){if(!CanSave)return;_saving=true;var a=decimal.Parse(Amount,CultureInfo.InvariantCulture);var row=new PromotionRecord(Selected?.Id??Promotions.Count+1,Name,Description,Start,End,a);if(Selected is null)Promotions.Add(row);else Promotions[Promotions.IndexOf(Selected)]=row;Selected=row;Feedback="Đã lưu thay đổi trên dữ liệu mẫu; chưa ghi chương trình thật.";_saving=false;Refresh();}
 private void Delete(){if(!CanDelete)return;Promotions.Remove(Selected!);Selected=null;Clear();Feedback="Đã xóa chương trình mẫu chưa gán đăng ký.";Refresh();}private void Clear(){Selected=null;Name=Description=Amount="";Start=DateTime.Today;End=DateTime.Today.AddDays(7);Refresh();}
 private void Refresh(){OnPropertyChanged(nameof(Validation));OnPropertyChanged(nameof(IsAssigned));OnPropertyChanged(nameof(CanDelete));OnPropertyChanged(nameof(HasNoData));SaveCommand?.NotifyCanExecuteChanged();DeleteCommand?.NotifyCanExecuteChanged();}
}
